{
  "hooks": {
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v folkways >/dev/null 2>&1 || { echo 'folkways is not installed, so its hooks are off: https://github.com/sumsolution/folkways#install'; exit 0; }; folkways hook session-start"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v folkways >/dev/null 2>&1 || exit 0; folkways hook context-band"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "command -v folkways >/dev/null 2>&1 || exit 0; folkways hook git-guard"
          }
        ]
      }
    ],
    "PostToolBatch": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v folkways >/dev/null 2>&1 || exit 0; folkways hook context-band"
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "command -v folkways >/dev/null 2>&1 || exit 0; folkways hook precompact"
          }
        ]
      }
    ]
  },
  "disableAllHooks": false,
  "permissions": {
    "ask": [
      "Bash(git push:*)"
    ]
  }
}
